INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24015, 110501, 4, 1, 4, "2030/12/17 14:59:59", 0.0, 0.0, "カオリ（サマー）", "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24016, 110501, 1, 2, 4, "2030/12/17 14:59:59", 4.0, 0.0, "カオリ（サマー）", "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24017, 110501, 4, 3, 4, "2030/12/17 14:59:59", 0.0, 0.0, "カオリ（サマー）", "マジムンだらけで目が回るさ～！\nふらふらさ～！", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24018, 110501, 2, 4, 1, "2030/12/17 14:59:59", 5.2, 0.0, "カオリ（サマー）", "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24019, 110501, 6, 5, 5, "2030/12/17 14:59:59", 4.2, 0.0, "カオリ（サマー）", "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24020, 110501, 2, 6, 2, "2030/12/17 14:59:59", 0.0, 0.0, "カオリ（サマー）", "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24021, 110501, 6, 7, 1, "2030/12/17 14:59:59", 6.4, 0.0, "カオリ（サマー）", "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24022, 110501, 2, 8, 2, "2030/12/17 14:59:59", 0.0, 0.0, "カオリ（サマー）", "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24023, 110501, 3, 9, 6, "2030/12/17 14:59:59", 10.08, 0.0, "カオリ（サマー）", "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24024, 110501, 2, 10, 1, "2030/12/17 14:59:59", 5.0, 0.0, "カオリ（サマー）", "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES ("2019/07/31 12:00:00", 10021, 24, 24025, 110501, 2, 11, 2, "2030/12/17 14:59:59", 0.0, 0.0, "カオリ（サマー）", "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 0.0);
